const GATE_VERSION = 'v001';
const REAL_INSTALLER_NAME = 'install_team_chart_presentation_cleanup_v001_20260920_010207pm.php';
const REAL_INSTALLER_SHA256 = 'b8eb0c2aed44af6fc8c3c7a85244f4b5266cb50086317717563972fb0aef4455';
const REAL_INSTALLER_B64 = '';

function h($value): string
{
    return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');
}

function lint_php_file(string $path): array
{
    if (!function_exists('shell_exec')) {
        return ['ok'=>false, 'output'=>'shell_exec() is not available.'];
    }

    $output = @shell_exec('php -l ' . escapeshellarg($path) . ' 2>&1');

    if ($output === null) {
        return ['ok'=>false, 'output'=>'[NULL returned by shell_exec()]'];
    }

    $output = trim((string)$output);

    return [
        'ok' => stripos($output, 'No syntax errors detected') !== false,
        'output' => $output,
    ];
}

$realPath = __DIR__ . '/' . REAL_INSTALLER_NAME;
$action = (string)($_POST['action'] ?? '');
$message = '';
$messageClass = 'info';
$lint = null;

if ($action === 'stage') {
    $payload = base64_decode(REAL_INSTALLER_B64, true);

    if ($payload === false) {
        $message = 'FAIL — embedded installer payload could not be decoded.';
        $messageClass = 'bad';
    } elseif (hash('sha256', $payload) !== REAL_INSTALLER_SHA256) {
        $message = 'FAIL — embedded installer payload hash did not match.';
        $messageClass = 'bad';
    } else {
        if (is_file($realPath)) {
            $existing = (string)@file_get_contents($realPath);

            if (hash('sha256', $existing) !== REAL_INSTALLER_SHA256) {
                $message = 'FAIL — a different file already exists with the real installer filename. Nothing was overwritten.';
                $messageClass = 'bad';
            }
        }

        if ($message === '' && !is_file($realPath)) {
            if (@file_put_contents($realPath, $payload, LOCK_EX) === false) {
                $message = 'FAIL — could not stage the real installer file.';
                $messageClass = 'bad';
            } else {
                @chmod($realPath, 0644);
            }
        }

        if ($message === '') {
            $lint = lint_php_file($realPath);

            if (!empty($lint['ok'])) {
                $message = 'PASS — real installer staged with the exact filename and PHP lint passed.';
                $messageClass = 'good';
            } else {
                $message = 'FAIL — real installer was staged but did not pass PHP lint.';
                $messageClass = 'bad';
            }
        }
    }
}

if ($lint === null && is_file($realPath)) {
    $current = (string)@file_get_contents($realPath);

    if (hash('sha256', $current) === REAL_INSTALLER_SHA256) {
        $lint = lint_php_file($realPath);
    }
}

$ready = is_file($realPath)
    && $lint !== null
    && !empty($lint['ok'])
    && hash_file('sha256', $realPath) === REAL_INSTALLER_SHA256;

?>
